request.user_message:
Abstract the following semantic predicate cluster into exactly one reusable predicate.

Cluster ID:
ternary-007

Cluster Arity:
3

Cluster Members:
[
  {
    "name": "CORROBORATES_RESULT_WITH_INDEPENDENT_PATH",
    "definition": "A previously obtained result is recomputed through a materially different data-access or implementation path in order to check for agreement, and the second observation reproduces the same value for the same quantity.",
    "parameters": [
      {
        "name": "baseline_result",
        "type": "observation",
        "description": "The observation reporting the first computed value produced by the original implementation path."
      },
      {
        "name": "validation_action",
        "type": "action",
        "description": "The action recomputing the same quantity through a materially different data-access or implementation path."
      },
      {
        "name": "validation_result",
        "type": "observation",
        "description": "The observation reporting the recomputed value obtained from the alternative path."
      }
    ],
    "assertion_conditions": [
      "The baseline observation reports a specific computed value.",
      "The validation action uses a different loading, access, or implementation path than the one that produced the baseline value (for example a different library, interface, or format reader for the same underlying data).",
      "The validation observation reports the same value for the same quantity as the baseline, so the independent paths agree."
    ],
    "exclusion_conditions": [
      "The second run repeats the identical code or access path, so agreement is not informative.",
      "The recomputed quantity, scope, or selection differs from the baseline.",
      "The two observations report different values, or no baseline value exists.",
      "The second observation only inspects the persisted output rather than recomputing the quantity."
    ]
  },
  {
    "name": "VERIFIES_CANDIDATE_BY_TARGETED_REEXTRACTION",
    "definition": "A proposed candidate or candidate fragment is checked by re-reading the exact stored location, offset, or field from which it was claimed to originate, and the returned data are compared with the candidate to confirm or refute it.",
    "parameters": [
      {
        "name": "verification_reasoning",
        "type": "reasoning",
        "description": "The reasoning selecting the candidate and the exact location or field to re-read."
      },
      {
        "name": "extraction_action",
        "type": "action",
        "description": "The action that retrieves data from the identified location."
      },
      {
        "name": "extraction_result",
        "type": "observation",
        "description": "The observation reporting the retrieved data for comparison with the candidate."
      }
    ],
    "assertion_conditions": [
      "The verification_reasoning identifies a candidate or fragment and a specific location, offset, or field to inspect.",
      "The extraction_action retrieves data from that identified location rather than performing an untargeted search.",
      "The extraction_result contains data that can be directly compared with the candidate, confirming or refuting it."
    ],
    "exclusion_conditions": [
      "The action is an untargeted exploration not tied to a proposed candidate.",
      "The retrieved data cannot be compared with the candidate.",
      "The reasoning does not identify what is being verified or where it should be found.",
      "The action independently recomputes the candidate through a different path rather than re-reading the claimed source location."
    ]
  },
  {
    "name": "VERIFIES_EQUIVALENCE_AGAINST_REFERENCE",
    "definition": "The reasoning states a tolerance within which candidate outputs must match an independent reference implementation; the action evaluates candidate and reference computations on identical inputs; and the observation reports quantified deviations or explicit equality that can be judged against that tolerance.",
    "parameters": [
      {
        "name": "tolerance_reasoning",
        "type": "reasoning",
        "description": "The agent text stating the required equivalence or tolerance that candidate outputs must meet relative to the reference implementation."
      },
      {
        "name": "comparison_action",
        "type": "action",
        "description": "The action that runs both the candidate and the reference computation on the same inputs and obtains their differences."
      },
      {
        "name": "deviation_observation",
        "type": "observation",
        "description": "The observation reporting the quantified differences or explicit equality between candidate and reference outputs."
      }
    ],
    "assertion_conditions": [
      "The reasoning states a tolerance or equivalence requirement for matching the outputs of an independent reference implementation.",
      "The action evaluates both the candidate and the reference on identical inputs within the same check.",
      "The observation reports quantified deviations or explicit equality for the compared quantities, sufficient to judge compliance with the stated tolerance."
    ],
    "exclusion_conditions": [
      "The action runs only the candidate implementation, with no reference computation in the same check.",
      "The observation reports only an unquantified pass or fail without comparison to reference outputs.",
      "The comparison uses an absolute expected value rather than an independently computed reference result.",
      "The reference side merely reuses the candidate's own computation path, so agreement is not informative."
    ]
  }
]

