["CONFIGURES_EVENT_DRIVEN_AUTOMATION", "PREVENTS_SELF_CAUSED_ADVERSE_EFFECTS_THROUGH_CORRECTIVE_ACTION", "EVALUATES_CANDIDATE_AGAINST_ENUMERATED_CONSTRAINTS_OR_SCENARIOS", "RESOLVES_EVALUATED_CANDIDATE_ELEMENTS_TO_SINGLE_RESULT", "INTERPRETS_REQUIREMENTS_FOR_ACTION_ADMISSIBILITY", "INITIATES_DETACHED_ASYNCHRONOUS_EXECUTION", "REPORTS_ABSENT_OR_UNAVAILABLE_CAPABILITY", "IDENTIFIES_SPECIFIC_POTENTIAL_FAILURE_MODE", "ASSESSES_COMPETING_ACCOUNTS_OF_SAME_OBSERVATION", "ESTABLISHES_EVIDENCE_GROUNDED_TASK_OUTCOME_REFERENCE", "FORMULATES_STRUCTURED_OPERATIVE_ACCOUNT", "SPECIFIES_TARGET_LINKED_CONCRETE_MEANS", "GROUNDS_COMPUTATIONAL_ASSESSMENT_IN_QUANTITATIVE_ANALYSIS", "ANTICIPATES_PROSPECTIVE_VERIFICATION", "DELIMITS_MODIFICATION_AND_RESIDUAL_ARTIFACT_SCOPE", "IDENTIFIES_DEFICIENCY_OR_INCOMPLETENESS", "REPRODUCES_SPECIFIED_PROCEDURE_OR_OPERATION_ORDER", "IMPLEMENTS_LIMITATION_RESPONSIVE_ALTERNATIVE_APPROACH", "EXECUTES_REASONED_REMOVAL_OF_UNWANTED_STATE", "RESOLVES_CANDIDATE_STATUS_FROM_OBSERVED_EVIDENCE", "GROUNDS_REASONING_SPECIFICATION_IN_OBSERVED_ACTION_OR_STATE", "MATERIALIZES_SPECIFIED_CONTENT_IN_DESIGNATED_ARTIFACT", "INTERPRETS_PROBLEMATIC_OBSERVATION_FOR_UNDERSTANDING_OR_RESPONSE", "GROUNDS_CONSTRAINT_OR_JUDGMENT_IN_OBSERVED_EVIDENCE", "CONFIRMS_INTENDED_EFFECT_OR_REQUIRED_STATE_FROM_OBSERVED_RESULT", "PRESERVES_VERIFIED_SUBSTANCE_DURING_REPRESENTATIONAL_REVISION", "CONSTRAINT_DRIVEN_ARTIFACT_ELIMINATION_OR_REVISION", "GENERALIZES_INFERRED_RULE_BEYOND_OBSERVED_EXAMPLES", "RECONSTRUCTS_ANCESTRY_OR_DIVERGENCE_FROM_VERSION_IDENTIFIERS", "INTEGRATES_MULTIPLE_OBSERVATIONS_INTO_UNIFIED_REPRESENTATION", "DIRECTS_INVESTIGATIVE_FOCUS_FROM_OBSERVED_FEATURE", "INTERPRETS_OBSERVED_CONTENT_AS_TYPED_OR_STRUCTURED_INFORMATION", "DERIVES_GOVERNING_ARTIFACT_JUDGMENT_FROM_OBSERVED_CONTENT", "DISCRIMINATES_BENIGN_REFERENCE_OCCURRENCES_FROM_ACTUAL_TARGETS", "RECORDS_DURABLE_ARTIFACT_STATE_REFERENCE_FOR_COMPARISON_OR_HISTORY", "PERSISTS_VALIDATED_STATE_TO_AUTHORITATIVE_STORE", "DERIVES_CONCRETE_TARGET_LOCATION_FROM_OBSERVED_LAYOUT_METADATA", "RESOLVES_TASK_RELEVANT_PREREQUISITE_OR_ENVIRONMENT_STATE", "CONDUCTS_CONCERN_MOTIVATED_EVIDENCE_GATHERING", "IMPLEMENTS_REASONED_FAILURE_OR_RISK_RESPONSE_WITH_OBSERVED_EVIDENCE", "RECOVERS_UNUSABLE_CHECK_RESULT_VIA_METHOD_DIAGNOSIS_AND_ALTERNATIVE_RETRIEVAL", "CONFIRMS_ABSENCE_OF_UNWANTED_STATE_OR_CONTENT", "INTERPRETS_OBSERVED_STRUCTURE_OR_INFORMATIONAL_GAP_TO_DIRECT_TARGETED_ACTION"]

Read every member's complete definition, ordered parameters, assertion conditions, and exclusion conditions. Identify the common underlying behavioral mechanism and generate exactly one complete predicate following the system instructions. The new predicate must preserve the cluster arity. Use a unique predicate name that does not conflict with previously generated predicate names. Return only the complete five-field JSON predicate.

message.content:
{
  "name": "VERIFIES_CLAIM_OR_RESULT_VIA_INDEPENDENT_COMPARISON",
  "definition": "A previously obtained result, proposed candidate, or candidate output is checked by performing an independent comparison: recomputing the same quantity through a materially different access or implementation path, re-reading the exact claimed source location or field, or evaluating candidate and reference computations on identical inputs against a stated equality or tolerance standard. An observation then reports comparable data that confirm or refute the claim by agreement, disagreement, or quantified deviation.",
  "parameters": [
    {
      "name": "verification_standard",
      "type": "reasoning",
      "description": "The reasoning or stated standard identifying what is being verified, including the prior result, candidate or fragment, claimed source location, reference output, quantity, or tolerance criterion against which agreement is to be judged."
    },
    {
      "name": "independent_comparison_action",
      "type": "action",
      "description": "The action that obtains independent comparison evidence by recomputing through a materially different access or implementation path, re-extracting targeted data from the claimed source location, or evaluating candidate and reference computations on identical inputs."
    },
    {
      "name": "comparison_observation",
      "type": "observation",
      "description": "The observation reporting the independently obtained value, data, quantified deviation, or explicit equality for the same quantity, scope, inputs, or location, sufficient to confirm or refute the target against the verification standard."
    }
  ],
  "assertion_conditions": [
    "The verification_standard identifies a specific quantity, claim, candidate, source location, reference output, or tolerance that is to be checked.",
    "The independent_comparison_action is targeted to that verification target and obtains comparison evidence by a materially different access or implementation path, by re-reading the exact claimed source location or field, or by evaluating candidate and reference computations on identical inputs.",
    "The comparison_observation reports a value, dataset, quantified deviation, or explicit equality directly comparable with the verification target, so agreement or disagreement can be determined.",
    "The comparison path is materially distinct from, or specifically targeted to, the claimed source or computation being checked, making the observed agreement or disagreement informative."
  ],
  "exclusion_conditions": [
    "The comparison repeats the identical code or access path, or reuses the candidate's own computation path, so agreement is not informative.",
    "The compared quantity, scope, selection, inputs, or source location differs from the target being verified.",
    "No baseline result, candidate, reference output, or verification criterion exists against which the comparison observation can be judged.",
    "The action is untargeted exploration not tied to the proposed result, candidate, or claimed source location.",
    "The observation only inspects a persisted output without recomputing or re-reading when comparable evidence from an independent or targeted path is required.",
    "The observation reports only an unquantified pass or fail, or data that cannot be compared with the verification target."
  ]
}

